package devicemonitor.presentation.report

import com.google.gson.Gson
import devicemonitor.data.device.LayoutInspectorSnapshot
import java.io.File
import java.nio.file.Files
import java.nio.file.StandardCopyOption
import java.time.ZoneId
import java.time.format.DateTimeFormatter
import java.util.Base64

object LayoutInspectorReport {
    fun writeHtml(snapshot: LayoutInspectorSnapshot, output: File): File {
        output.absoluteFile.parentFile?.mkdirs()
        val html = html(snapshot)
        val temp = Files.createTempFile(output.absoluteFile.parentFile.toPath(), ".layout-inspector-", ".tmp")
        try {
            Files.writeString(temp, html)
            Files.move(temp, output.toPath(), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE)
        } catch (e: java.nio.file.AtomicMoveNotSupportedException) {
            Files.move(temp, output.toPath(), StandardCopyOption.REPLACE_EXISTING)
        } finally {
            Files.deleteIfExists(temp)
        }
        return output
    }

    internal fun html(snapshot: LayoutInspectorSnapshot): String {
        val image = Base64.getEncoder().encodeToString(snapshot.screenshotPng)
        val elements = Gson().toJson(snapshot.hierarchy.elements)
        val serial = Gson().toJson(snapshot.serial)
        val captured = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss z")
            .withZone(ZoneId.systemDefault()).format(snapshot.capturedAt)
        val status = if (snapshot.hierarchy.truncated) "First 5,000 nodes shown" else "Complete hierarchy"
        return TEMPLATE
            .replace("__SERIAL_TEXT__", htmlEscape(snapshot.serial))
            .replace("__SERIAL_JSON__", serial)
            .replace("__CAPTURED__", htmlEscape(captured))
            .replace("__WIDTH__", snapshot.screenWidth.toString())
            .replace("__HEIGHT__", snapshot.screenHeight.toString())
            .replace("__COUNT__", snapshot.hierarchy.elements.size.toString())
            .replace("__ROTATION__", snapshot.hierarchy.rotation?.toString() ?: "unavailable")
            .replace("__STATUS__", status)
            .replace("__IMAGE__", image)
            .replace("__ELEMENTS__", elements)
    }

    private fun htmlEscape(value: String): String = value.replace("&", "&amp;").replace("<", "&lt;")
        .replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&#39;")

    private val TEMPLATE = """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:; connect-src 'self'; base-uri 'none'; form-action 'none'">
<title>Layout Inspector</title><style>
:root{color-scheme:dark;--bg:#090a0b;--panel:#121313;--well:#0c0d0d;--line:#2b2d2d;--strong:#454747;--text:#f2efe8;--muted:#aaa59c;--quiet:#77736d;--gold:#e8b66d;--violet:#9e8cff;--teal:#58d6c7;--red:#ff7676}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,#211b12 0,transparent 28%),radial-gradient(circle at 92% 4%,#171329 0,transparent 24%),var(--bg);color:var(--text);font:13px/1.45 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input{font:inherit}main{width:min(1240px,calc(100% - 28px));margin:auto;padding:28px 0 34px}.top{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:18px}.eyebrow{margin:0;color:var(--gold);font:800 9px/1.2 ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase}h1{margin:6px 0 5px;font-size:clamp(28px,4vw,48px);line-height:1;letter-spacing:-.045em}.lede{margin:0;color:var(--muted)}.actions{display:flex;align-items:center;gap:8px}.button{min-height:38px;padding:0 13px;border:1px solid var(--line);border-radius:10px;color:var(--text);background:rgba(255,255,255,.04);cursor:pointer;font-size:10px;font-weight:760}.button:hover{border-color:var(--strong);background:rgba(255,255,255,.07)}.button.primary{color:#15120d;border-color:var(--gold);background:var(--gold)}.button:disabled{opacity:.45;cursor:not-allowed}.refresh-state{min-height:20px;margin:7px 0 0;color:var(--quiet);font-size:9px;text-align:right}.facts{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-bottom:14px}.fact{padding:11px;border:1px solid var(--line);border-radius:11px;background:rgba(18,19,19,.88)}.fact span{display:block;color:var(--quiet);font-size:8px;letter-spacing:.09em;text-transform:uppercase}.fact b{display:block;margin-top:4px;overflow-wrap:anywhere;font-size:11px}.workspace{display:grid;grid-template-columns:minmax(260px,380px) minmax(0,1fr);gap:14px;align-items:start}.panel{border:1px solid var(--line);border-radius:16px;background:rgba(18,19,19,.94);box-shadow:0 18px 50px rgba(0,0,0,.2)}.screen-panel{position:sticky;top:14px;padding:14px}.screen-head,.list-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:11px}.screen-head strong,.list-head strong{font-size:11px}.screen-head span,.list-head span{color:var(--quiet);font-size:9px}.screen{position:relative;overflow:hidden;width:100%;border:1px solid var(--line);border-radius:12px;background:#000}.screen img{display:block;width:100%;height:auto}.overlay{position:absolute;z-index:1;padding:0;border:1px solid rgba(158,140,255,.42);background:rgba(158,140,255,.035);cursor:pointer}.overlay:hover{z-index:2;border-color:var(--gold);background:rgba(232,182,109,.12)}.overlay.selected{z-index:3;border:2px solid var(--teal);background:rgba(88,214,199,.13);box-shadow:0 0 0 2px rgba(9,10,11,.75)}.detail{margin-top:11px;padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--well)}.detail h2{margin:0 0 6px;font-size:13px;overflow-wrap:anywhere}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.detail-grid div{min-width:0}.detail-grid span{display:block;color:var(--quiet);font-size:8px;text-transform:uppercase}.detail-grid b{display:block;margin-top:2px;overflow-wrap:anywhere;font-size:9px}.state-chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:9px}.chip{padding:4px 6px;border:1px solid var(--line);border-radius:6px;color:var(--quiet);font:8px/1 ui-monospace,monospace}.chip.on{color:#bffcf5;border-color:rgba(88,214,199,.26);background:rgba(88,214,199,.06)}.list-panel{min-width:0;padding:14px}.search{width:100%;height:39px;margin-bottom:10px;padding:0 11px;border:1px solid var(--line);border-radius:10px;outline:0;color:var(--text);background:var(--well)}.search:focus{border-color:rgba(232,182,109,.55);box-shadow:0 0 0 3px rgba(232,182,109,.08)}.rows{display:grid;gap:7px;max-height:720px;overflow:auto;padding-right:3px}.row{display:grid;grid-template-columns:35px minmax(0,1fr) auto;gap:10px;align-items:start;width:100%;padding:10px;border:1px solid var(--line);border-radius:11px;color:var(--text);background:rgba(0,0,0,.18);text-align:left;cursor:pointer}.row:hover,.row.selected{border-color:rgba(158,140,255,.55);background:rgba(158,140,255,.055)}.row.selected{box-shadow:inset 3px 0 var(--teal)}.index{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:var(--gold);background:rgba(232,182,109,.08);font:800 9px/1 ui-monospace,monospace}.row-main{min-width:0}.row-main strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px}.row-main small{display:block;margin-top:4px;overflow:hidden;color:var(--quiet);font-size:8px;text-overflow:ellipsis;white-space:nowrap}.bounds{color:var(--quiet);font:8px/1.35 ui-monospace,monospace;text-align:right}.empty{padding:28px;color:var(--quiet);text-align:center}.notice{margin-bottom:12px;padding:9px 11px;border:1px solid rgba(232,182,109,.2);border-radius:10px;color:#dbc7a9;background:rgba(232,182,109,.05);font-size:9px}.notice.error{border-color:rgba(255,118,118,.25);color:#ffc1c1;background:rgba(255,118,118,.06)}@media(max-width:820px){.top{align-items:flex-start;flex-direction:column}.actions{width:100%}.facts{grid-template-columns:repeat(2,1fr)}.workspace{grid-template-columns:1fr}.screen-panel{position:static}.screen{max-width:360px;margin:auto}.rows{max-height:none}.refresh-state{text-align:left}}@media(max-width:480px){main{width:min(100% - 18px,1240px)}.facts{grid-template-columns:1fr}.detail-grid{grid-template-columns:1fr}.row{grid-template-columns:31px minmax(0,1fr)}.bounds{grid-column:2;text-align:left}}
</style></head><body><main>
<header class="top"><div><p class="eyebrow">Offline Android structure</p><h1>Lite Layout Inspector</h1><p class="lede">Click an element to connect Android metadata with its exact screen position.</p></div><div><div class="actions"><button class="button primary" id="refresh" type="button">Refresh screen</button></div><p class="refresh-state" id="refreshState" role="status"></p></div></header>
<section class="facts"><div class="fact"><span>Target</span><b>__SERIAL_TEXT__</b></div><div class="fact"><span>Screen</span><b>__WIDTH__ × __HEIGHT__</b></div><div class="fact"><span>Elements</span><b>__COUNT__</b></div><div class="fact"><span>Rotation</span><b>__ROTATION__</b></div><div class="fact"><span>Captured</span><b>__CAPTURED__</b></div></section>
<div class="notice">__STATUS__. Layout captures can include visible text and screen imagery; this file stays local and is not added to support bundles automatically.</div>
<section class="workspace"><article class="panel screen-panel"><div class="screen-head"><strong>Device screen</strong><span>select a boundary</span></div><div class="screen" id="screen"><img src="data:image/png;base64,__IMAGE__" alt="Captured Android screen"><div id="overlays"></div></div><div class="detail" id="detail"><h2>Select an element</h2><div class="empty">Element metadata will appear here.</div></div></article>
<article class="panel list-panel"><div class="list-head"><strong>UI elements</strong><span id="visibleCount">__COUNT__ shown</span></div><input class="search" id="search" type="search" autocomplete="off" placeholder="Search type, resource ID, text or description"><div class="rows" id="rows"></div></article></section>
</main><script>
var SERIAL=__SERIAL_JSON__,SCREEN_W=__WIDTH__,SCREEN_H=__HEIGHT__,ELEMENTS=__ELEMENTS__,selectedIndex=null;
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function value(v){return v==null||v===''?'Unavailable':v;}
function typeOf(e){var c=e.className||'Unknown',parts=c.split('.');return parts[parts.length-1]||'Unknown';}
function boundsText(e){var b=e.bounds;return '['+b.left+','+b.top+']['+b.right+','+b.bottom+']';}
function widthOf(e){return Math.max(0,e.bounds.right-e.bounds.left);}function heightOf(e){return Math.max(0,e.bounds.bottom-e.bounds.top);}function centerXOf(e){return e.bounds.left+Math.floor(widthOf(e)/2);}function centerYOf(e){return e.bounds.top+Math.floor(heightOf(e)/2);}
function searchText(e){return [typeOf(e),e.className,e.resourceId,e.text,e.contentDescription,e.packageName,boundsText(e)].join(' ').toLowerCase();}
function overlayStyle(e){var b=e.bounds,left=Math.max(0,Math.min(SCREEN_W,b.left)),top=Math.max(0,Math.min(SCREEN_H,b.top)),right=Math.max(left,Math.min(SCREEN_W,b.right)),bottom=Math.max(top,Math.min(SCREEN_H,b.bottom));return'left:'+(left/SCREEN_W*100)+'%;top:'+(top/SCREEN_H*100)+'%;width:'+((right-left)/SCREEN_W*100)+'%;height:'+((bottom-top)/SCREEN_H*100)+'%';}
function render(){var q=document.getElementById('search').value.trim().toLowerCase(),visible=ELEMENTS.filter(function(e){return!q||searchText(e).indexOf(q)>=0;});document.getElementById('visibleCount').textContent=visible.length+' shown';document.getElementById('rows').innerHTML=visible.length?visible.map(function(e){return'<button class="row'+(e.index===selectedIndex?' selected':'')+'" type="button" data-index="'+e.index+'" style="--depth:'+Math.min(e.depth,8)+'"><span class="index">'+e.index+'</span><span class="row-main"><strong>'+esc(typeOf(e))+'</strong><small>'+esc(value(e.resourceId))+(e.text?' · '+esc(e.text):'')+'</small></span><span class="bounds">'+esc(boundsText(e))+'<br>'+widthOf(e)+' × '+heightOf(e)+'</span></button>';}).join(''):'<div class="empty">No elements match this search.</div>';document.getElementById('overlays').innerHTML=visible.filter(function(e){return widthOf(e)>0&&heightOf(e)>0;}).map(function(e){return'<button class="overlay'+(e.index===selectedIndex?' selected':'')+'" type="button" aria-label="'+esc(typeOf(e)+' '+value(e.resourceId))+'" data-index="'+e.index+'" style="'+overlayStyle(e)+'"></button>';}).join('');Array.prototype.forEach.call(document.querySelectorAll('[data-index]'),function(node){node.onclick=function(){select(Number(node.dataset.index),node.classList.contains('overlay'));};});}
function select(index,fromOverlay){selectedIndex=index;var e=ELEMENTS.filter(function(item){return item.index===index;})[0];if(!e)return;var states=['enabled','clickable','focusable','focused','scrollable','selected','checked','password'];document.getElementById('detail').innerHTML='<h2>'+esc(typeOf(e))+'</h2><div class="detail-grid"><div><span>Resource ID</span><b>'+esc(value(e.resourceId))+'</b></div><div><span>Class</span><b>'+esc(value(e.className))+'</b></div><div><span>Position</span><b>'+esc(boundsText(e))+'</b></div><div><span>Size / center</span><b>'+widthOf(e)+' × '+heightOf(e)+' · '+centerXOf(e)+', '+centerYOf(e)+'</b></div><div><span>Text</span><b>'+esc(value(e.text))+'</b></div><div><span>Content description</span><b>'+esc(value(e.contentDescription))+'</b></div><div><span>Package</span><b>'+esc(value(e.packageName))+'</b></div><div><span>Hierarchy depth</span><b>'+e.depth+'</b></div></div><div class="state-chips">'+states.map(function(k){return'<span class="chip'+(e[k]?' on':'')+'">'+k+' '+(e[k]?'yes':'no')+'</span>';}).join('')+'</div>';render();if(fromOverlay){var row=document.querySelector('.row[data-index="'+index+'"]');if(row)row.scrollIntoView({block:'nearest'});}}
function refresh(){var btn=document.getElementById('refresh'),state=document.getElementById('refreshState');if(location.protocol==='file:'){state.textContent='Refresh is available inside ADB Performance Studio.';return;}btn.disabled=true;state.textContent='Capturing current screen…';var p=new URLSearchParams();p.set('serial',SERIAL);fetch('/api/layout-inspector',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:p.toString()}).then(function(r){return r.json().then(function(b){if(!r.ok||b.ok===false)throw new Error(b.error||'Refresh failed');return b;});}).then(poll).catch(function(e){btn.disabled=false;state.textContent=e.message;});}
function poll(){fetch('/api/layout-inspector-status').then(function(r){return r.json();}).then(function(d){if(d.error)throw new Error(d.error);if(d.done){location.replace('/api/layout-inspector-report?v='+Date.now());return;}document.getElementById('refreshState').textContent='Refreshing… '+(d.progress||0)+'%';setTimeout(poll,500);}).catch(function(e){document.getElementById('refresh').disabled=false;document.getElementById('refreshState').textContent=e.message;});}
document.getElementById('search').addEventListener('input',render);document.getElementById('refresh').addEventListener('click',refresh);if(location.protocol==='file:'){document.getElementById('refresh').disabled=true;document.getElementById('refreshState').textContent='Static offline capture';}render();if(ELEMENTS.length)select(ELEMENTS[0].index,false);
</script></body></html>"""
